import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"井","description":"高島易斷 - 井","frontmatter":{"title":"井","description":"高島易斷 - 井"},"headers":[],"relativePath":"classics/takashima/048.md","filePath":"classics/takashima/048.md"}'),i={name:"classics/takashima/048.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="井" tabindex="-1">井 <a class="header-anchor" href="#井" aria-label="Permalink to “井”">​</a></h1><h2 id="井-1" tabindex="-1">井 <a class="header-anchor" href="#井-1" aria-label="Permalink to “井”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>井：改邑不改井，無喪無得，往來井井。汔至，亦未繘井，贏其瓶，兇。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>“井”，通也，物所通用也。古者建設都邑，必鑿井以養民，即或邑有改遷，而井之制不改。人得井以為養，而井不因之見損，故“無喪”；井所以養人，而井不以此見功，故“無得”。但見往者往，來者來，人之就養於井者，亦未嘗歸功於井也。“繘”，所以引而下，“瓶”，所以盛而上，至若繘未下，而瓶已羸，則井為虛設，而繘亦為虛懸矣，故曰“兇”。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>木上有水，井。君子以勞民勸相。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>《坎》為水，在上，《巽》為木，在下，其象為“木上有水”，即《彖傳》所謂“巽乎水而上水”之象也。君子玩其象，而修其德，以之“勞民勸相”。“勞”，用民力也，“勸”，勸道也，“相”，輔相也。《坎》為勞卦，互卦《兌》，《兌》為悅，悅以勞民；《兌》又為口，《巽》為同，為交，有同心協助之象，故曰“相”。天下之民無窮，一人之養難周，君子於是勞來之，勸相之，使比間族黨相親，貧窮患難相恤，開導誘掖，以盡其相生相養之道，如是則所以養民者，周恤完全，而無一人之漏養者，所謂“井養而不窮”也。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：目下交木水相生之運，正可相助成事。</p><p>○　問戰徵：有水滅木之象，水軍有厄，宜勞力相助，可以出險。</p><p>○　問功名：“木上有水”，有得春雨發生之象，功名可望。</p><p>○　問營商：有利過於本之象，吉。</p><p>○　問家宅：此屋棟柱，恐有水溼潰爛之患，宜急修葺。</p><p>○　一問婚姻：《坎》男《巽》女；男上於女，陰陽之正也，吉。</p><p>○　問疾病：腎水暴溢，宜急調治。</p><p>○　問六甲：生男。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>“舊井”者，壞而不治之井也；“禽”者，轆轤之軸，運繘者也，軸上刻以禽形，故曰“禽”。或謂軸轉之音，似禽鳴也。初居最下，象井底，水涸泥汙，故曰“井泥不食”，成為廢井，井久有毒，故人不食。其井既廢，則轆轤之禽，亦腐朽而無有矣，故曰“舊井無禽”。《象傳》以“下也”釋“井泥”，謂泥在井下，故不可食，以“時舍”釋“舊井”，謂井已廢舊，故為時所舍。按：《魯語》“取名魚，登川禽”，韋昭注：川禽，鰲蜃之屬。《易林》《遁》之《井》曰：“老河空虛，舊井無魚。”此無禽即蜃蛤魚蛙之類，說亦有據。</p><h2 id="初六佔" tabindex="-1">初六佔 <a class="header-anchor" href="#初六佔" aria-label="Permalink to “初六佔”">​</a></h2><p>○　問時運：為時過運衰，不為世用。</p><p>○　問戰徵：有兵器朽舊，不剋制勝之患。</p><p>○　問營商：貨物陳腐，不可販售。</p><p>○　問功名：年老無用。</p><p>○　問疾病：是舊症也。不治。</p><p>○　問婚姻：人品卑下，雖屬舊親，不成。</p><p>○　問訟事：必不得直。</p><p>○　問六甲：生男，防難育。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>友人某來，請佔氣運，筮得《井》之《需》。</p><p>斷曰：井既舊，有泥無禽，是廢井也；在人則運退時衰，必見棄而無用也。佔者得此。知其人品行卑下，為人所棄，難望進用之日也。卦爻初與四應，初之舊井，得四修之，即可無咎。今足下猶舊井也，甘辱泥塗，不自悔改，故終為世棄，不可複用也。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>“井谷”者，泉穴也。《漢書·溝洫志》，“井下相通行水為井渠”，井固有旁穿孔穴，二動體《艮》，《艮》為穴也。“鮒”，魚之小者，《子夏傳》謂蝦蟆。《井》五月之卦，故有蝦蟆；《爾雅翼》，“鮒，鰿也”，今作鯽。二體《巽》，《巽》為風，風主蟲，蝦蟆與魚，要皆不離夫介鱗蟲類。“射鮒”者，古有射魚，《淮南子·時則訓》，“季冬之月，命漁師始漁，天子親往射魚”；《史記》：“秦始皇至芝罘射，得巨魚。”井谷無巨魚，所射者鮒耳。“甕”，盛水之器，與瓶相類，二至四互《兌》，象《兌》口，《巽》在下，象底穿，故曰“甕敝漏”，即《彖》所謂“羸其瓶”也。蓋《井》之為水，以上汲為功，而谷水下注，如敝甕之無底者，復何與於井養之功哉！而徒以射鮒為能，故君子所不取也。</p><h2 id="九二佔" tabindex="-1">九二佔 <a class="header-anchor" href="#九二佔" aria-label="Permalink to “九二佔”">​</a></h2><p>○　問時運：所得者小，所失者大矣。</p><p>○　問戰徵：誤中敵計，軍入幽谷，致破釜缺養而不得出。</p><p>○　問功名：弋獲虛名，其何能久？</p><p>○　問營商：為貪意外之財，致失本分之利。</p><p>○　問婚姻：門地卑微，聲名殘敗，不佳。</p><p>○　問家宅：此宅有廢井，井口殘破，水不可食。</p><p>○　問疾病：是下漏之症，醫治可愈。</p><p>○　問失物：物已敝敗，得亦無用。</p><p>○　問六甲：生男，防此兒有殘疾。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>友人某來，請佔氣運，筮得《井》之《蹇》。</p><p>斷曰：井曰“井養”，然井不能自養，亦在人取之以為養也；乃不取水而取鮒，取非所取，是失《井》之義也。今足下佔氣運，得《井》二爻，知足下素好學問，亦如井之有源；病在專尚旁門，不務正學，猶是谷水為井之旁穴，射鮒非井之應得，究何與於井養之義也？“甕敝漏”者，為言井水下注，如人之流品日下也。爻象實為足下示警，足下當求通曉世情，躬行實踐，毋徒盜虛譽也。</p><p>明治三十年，佔司法省氣運，筮得《井》之《蹇》。</p><p>斷曰：此卦下三爻為井中之水，上三爻為汲水以供用也，故下三爻不吉，上三爻皆吉。我國近來許外國人雜居，一仿歐美各邦規則，定為法律，在我國人居住歐美各邦者，亦受歐美之保護，故我國亦保護彼國旅人，如出一轍也。今佔得二爻，其立法恐有徒貪小利，轉致失其大體，謂之“井谷射鮒，甕敝漏”。司外務之任者，所宜注意焉。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>“渫”，治也，謂治井而不停汙也。初則“泥”，二則“漏”，三居《巽》之終，《巽》有潔齊之義，故為“井渫”。渫則泥去，漏塞，清潔可食。其有不食者，非井之咎也，猶人澡身浴德，惠澤足以養人，當局者莫之知，旁觀者知之矣。“我”，則旁觀自謂也，謂如此清泉，而竟棄之如遺，我則為之心側矣。井既浚治，則可汲而用者，莫如此井也，此而不用，不明甚矣，安得明王出而用之也？是眾人祈禱而求其用者也。“王”指五，三至五互《離》，故為明王。陽為福，喻王者登用賢才，則德澤單敷，遐邇受福，賢者之福，即明君之福，亦天下之福也。“並受其福”，是一井之利，遍及萬家也。（附言）《井》為《震》宮五世之卦，凡問疾厄，得下卦多不治。下卦變則瓶體破，不能汲水，即《彖》辭所謂“羸其瓶，兇”。補治其破，猶病者得醫而治也，兇尚可救。其象如此，餘二十年來，屢佔屢驗，無一或爽。</p><h2 id="九三佔" tabindex="-1">九三佔 <a class="header-anchor" href="#九三佔" aria-label="Permalink to “九三佔”">​</a></h2><p>○　問時運：懷才不用，命為之也。</p><p>○　問戰徵：兵器既修，士卒可用，惜無主將，以致士氣頹喪，為可惜也。</p><p>○　問營商：明見貨物輻輳，可以獲利，不知販運，徒諉無用耳。</p><p>○　問功名：有才無命，為世所棄；兩年後至五爻，可望登用。</p><p>○　問婚姻：目下不成，至五爻必得成就，須在二年後也。</p><p>○　問家宅：此宅必有舊井久湮，宜渫治之。得食此水，一家獲福，若不渫不食，大為可惜。</p><p>○　問疾病：必是心神不安之症，宜飲症泉可愈。</p><p>○　問六甲：生男。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>明治二十六年一月，祝賀新年，偶謁某貴顯，貴顯顧餘曰：近來有奇妙之《易》斷乎？餘曰：《易》象精微，誠心感格，無不奇妙。昨年十月間，與杉浦重剛諸君，會於星岡茶寮，為佔眾議院議會結局，得《井》三爻。當時政府與眾議院，意見不合，勢甚決裂，後上乞天裁，始得平允。是所謂井井有條者也。</p><p>斷曰：《井》，一也，而食者眾，所謂“往來井井”，有眾之象焉。想井之始鑿，賴眾而成，迨井既成，則眾皆得井而養，喻言議之建，賴眾而倡，迨議既定，則眾皆依議而行也。故在眾議院，主張人民生活尚多不足，為之節省官費，整理財政，意在開國家富足之源也。在政府，謂議員不諳政體，不通時事，以致兩議不協，譬如汲水者，來至井上，互論井水之清濁，而兩下停汲，終歸無用，究何濟乎？局外者未免為之心憂矣，即所謂“井渫不食，為我心側”者是也。政府既不允議院，議院欲力逼政府，彼此各執一見，遂至衝突，此勢之不能中止也，於是惟有仰求宸斷，即爻辭所謂“可用汲，王明，並受其福”是也。幸聖上至仁至明，能兩酌其平，政府有可讓者讓之，議院有可容者容之，於適宜之中，立預算之準，以使上下各得其情，斯天下“並受其福”矣。貴顯聞之，謂餘能臆測時事，特假《易》以立說也。餘曰：此乃《易》理之先機，能貫徹於事前，餘不過就《易》論《易》，而其時事之應驗，自不能出於《易》之外也。</p><p>明治二十三年七月，新瀉審判所長富田禎次郎氏來訪。氏，餘舊知也，不相見數年矣，得見之餘，互談契闊，氏曰：我今來訪，專為道謝往年《易》斷也。乃詳述從前求卜，得《井》之三爻。</p><p>辭曰：“井渫不食，為我心惻。可用汲，王明，並受其福。”是井水本清潔，無人汲之，井養之功無所施，喻人雖有才德，無人用之，則展布之能無所見，必得明王之賞識，拔而用之，斯不特一人受福，天下“並受其福”也。就爻位而推之，以五爻為任用之日，六爻當大任之時，蓋即在三年四年間也，謂當必有應驗也。至今日，斷詞一一靈驗，不爽毫釐，心竊喜之，特來致謝。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>“甃”者，以磚壘井，防井之敗壞者也。此卦三陽為泉，三陰為井，初六最下，曰“泥”，上六最上，曰“收”，四居其間，不失其正，故曰“甃”。凡井之壞，壞於汙濁不修，而井遂至於無用，四能甃之，故得“無咎”。有四之甃乃得有五之“寒泉”，是助五以養人，皆賴四之甃也。甃井之功，不可為不大矣。</p><h2 id="六四佔" tabindex="-1">六四佔 <a class="header-anchor" href="#六四佔" aria-label="Permalink to “六四佔”">​</a></h2><p>○　問時運：正當運途改變之時，宜自修飭，不特無咎，可望上進。</p><p>○　問營商：宜整理舊業，自可獲利。</p><p>○　問功名：修身立名，二三年後，可大得志。</p><p>○　問戰徵：詩云“修我矛戟，與子偕作”，在此時也。</p><p>○　問婚姻：尚須待時。</p><p>○　問家宅：此宅宜改修為吉。</p><p>○　問六甲：有弄瓦之象，生女。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>橫濱港町接近居留地，有魚鳥菜獸市場，此市場，依各國開港條約所設，其業最為繁盛。一日有友來，曰：近來橫濱市場上，商人大起爭論，遂至休業，有人慾出而調停，未得處理之方，特請一佔。筮得《井》之《大過》。</p><p>斷曰：就市中商業而論，彼此俱有關係，譬如汲井之用繘瓶也。有井而無繘瓶，則井水將何從而汲？有繘瓶而無井，則繘瓶亦終歸無用。同在此市場貿易，知益則俱益，害則俱害，兩相鬥必致兩敗也。今佔得三爻，曰“井甃，無咎”，“甃”者，治也，因井之敗壞而重修之也。今兩家商業，因此一爭，未免敗壞，出而修之者，是在四也。蓋四即為居中調停之人，得四調停，而後五之“寒泉”，可以復食。四與五相隔一爻，一爻當一月，則來月必可和解，重複舊業矣。</p><p>佔清法二國爭據安南事由。本年三四月啟釁，至今未得和戰的訊，諸新聞紙所揭，皆由街談巷說，未足信憑，餘因先筮清國，得《井》之《大過》。</p><p>斷曰：卦德為井養不窮，謂其井之大，而得其養者眾矣。以喻清國之大，物產豐饒，他邦皆願與貿易，受其潤澤。故已汲者去，未汲者來，其貿易之品物無盡，猶井水取之不竭也。但清國航海之術未精，不能由己自輸其物產，譬如井水不能自出，必待人汲之，而後能澤物。故今為安南事件，雖欲與法開戰，而終歸不戰者，亦如井水之不能自動，可知清國必不起戰也。萬一清國決計開戰，則於各國貿易，大有障礙，凡局外中立之國，必為之出而調停，曲意保護，猶是以磚壘井，不使汙濁之得入也。“井甃，無咎”，此之謂也。自《井》四至《革》四爻，為七年，今後七年，清國必有改革之變。諺曰“唇亡齒寒”，我國亦宜嚴整預備也。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>“冽”，水清也，井水在上，故冽。五為《坎》之主，位居中正，《坎》為寒泉，辰在子，子水也，屬北方，故寒。按水之性，冬則溫，夏則寒，是陰中納陽，陽中納陰，其性然也；《井》為五月之卦，是以冽而且寒。孟子曰，“夏日飲水，冬日飲湯”，當此仲夏，汲此寒泉而食之，為得其時焉。蓋《井》自三“渫”之，四“甃”之，則“泥”去“漏”塞，而五之“寒泉”乃出，復之者眾，斯受福者亦眾矣。王者德潤生民，遍及萬方，亦如是耳。《井》旁通為《噬嗑》，“《噬嗑》，食也”，故曰“井冽，寒泉食”。</p><h2 id="九五佔" tabindex="-1">九五佔 <a class="header-anchor" href="#九五佔" aria-label="Permalink to “九五佔”">​</a></h2><p>○　問時運：家道必寒，幸運得其時，可望進用。</p><p>○　問營商：井出寒泉，喻言財源之長也，可望獲利。</p><p>○　問功名：品行中正，可享鼎養之榮。</p><p>○　問家宅：有廉泉讓水之風。</p><p>○　問婚姻：家風清白，同甘共苦，夫婦之正也。</p><p>○　問疾病：是外寒內熱之症，宜服寒涼之劑。</p><p>○　問六甲：生女。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>明治二十二年，佔山縣伯氣運，筮得《井》之《升》。</p><p>斷曰：井者所以養人，然不汲之，則井泉雖冽，亦無所用其養，喻賢者澤足惠民，然不舉之，則賢才在下，亦無以施其惠。今佔山縣伯氣運，得《井》之五爻，知伯才德淵深，志操清潔，寒素起家，超升顯要，其惠澤之敷，一如“王明”“用汲”，“並受其福”於無窮也。爻曰：“井甃”，喻言伯之氣體清明也；曰“寒泉食”，喻言下民食伯之德者，恍若一酌寒泉，頓覺胞膈涼爽也。伯之恩惠無窮，伯之榮顯，亦未有艾也。此年山縣伯果任內閣總理。此佔辭，當時上申三條公與伊藤伯。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>“收”，謂轆轤收縮。“幕”井蓋也，“勿幕”者，即《彖》所云“往來井井”，汲者眾多，無晝無夜，取之不竭：在井固不擅其有，不私其利，任人汲灌，故“勿幕”也。上居《坎》之極，偶畫兩開，有“勿幕”之象。“孚”，指五，五為“王明”，能用汲者也。“元吉”，元，大也，謂井之利大，故吉亦大。“在上”者，謂上在井口，養人之功，從此而出。“大成”者，謂井養之道，至此而大成矣，凡爻辭陰柔在上，多不吉，在上“元吉”，惟《井》一卦而已。</p><h2 id="上六佔" tabindex="-1">上六佔 <a class="header-anchor" href="#上六佔" aria-label="Permalink to “上六佔”">​</a></h2><p>○　問時運：功德在世，信用在人，“大成，“元吉”，運之極盛者也。</p><p>○　問功名：有大用大受之象，非一官一邑之微也。</p><p>○　問營商：商務會集，利益浩繁，可久可大，無往不吉。</p><p>○　問婚姻：上應在三，三曰“並受其福”，知兩姓皆吉。</p><p>○　問戰徵：凡軍將發則撤幕，“勿幕”，即撤幕前進也。一戰功成，故曰“大成”。吉。</p><p>○　問疾病：幕亦作暮，言旦夕可即愈也，吉。</p><p>○　問六甲：生女。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>明治三十年，佔貿易景況，筮得《井》之《巽》。</p><p>斷曰：此卦下《巽》木，上坎水，即《彖》所云“巽乎水而上水”，是為汲引井水之象。至上爻，則井之功用已成，“勿幕”者，王弼所謂“不擅其有，不私其利”也。今外商與我商從事貿易，我國不自輸出，待外商舶運而往，猶井水之待人而汲。內三爻井水不食，為貨物不能旺銷，外三爻則泉美可食，汲取者眾。四爻當七八月，五爻當九十月，上爻已在井口，當十一二月，正是百貨輻輳，銷運興旺之時，即在生絲一業，大宗輸出，為貿易最好景況也。果於上半年，生絲商況不振，七八月以後，逐步發動，十一二月，時價漲至千弗以上，悉為外商所買，國內機織場，反為之休業焉。</p>',107)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
